class Zipper:
    def __init__(self, node, crumbs):
        # node is a dict like {"value": v, "left": ..., "right": ...} or None
        # crumbs is a list of tuples: (direction, parent_value, other_subtree)
        # direction is 'left' if we descended into left child, so other_subtree is parent's right
        # direction is 'right' if we descended into right child, so other_subtree is parent's left
        self.node = node
        self.crumbs = crumbs

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, [])

    def value(self):
        if self.node is None:
            return None
        return self.node.get("value")

    def set_value(self, value):
        if self.node is None:
            # setting value on None yields a node with that value and no children
            new_node = {"value": value, "left": None, "right": None}
        else:
            new_node = {
                "value": value,
                "left": self.node.get("left"),
                "right": self.node.get("right"),
            }
        return Zipper(new_node, list(self.crumbs))

    def left(self):
        if self.node is None:
            return None
        left_sub = self.node.get("left")
        if left_sub is None:
            return None
        parent_value = self.node.get("value")
        right_sub = self.node.get("right")
        new_crumbs = list(self.crumbs)
        new_crumbs.append(("left", parent_value, right_sub))
        return Zipper(left_sub, new_crumbs)

    def set_left(self, tree):
        if self.node is None:
            # if focus is None, create a node with left set to tree
            new_node = {"value": None, "left": tree, "right": None}
        else:
            new_node = {
                "value": self.node.get("value"),
                "left": tree,
                "right": self.node.get("right"),
            }
        return Zipper(new_node, list(self.crumbs))

    def right(self):
        if self.node is None:
            return None
        right_sub = self.node.get("right")
        if right_sub is None:
            return None
        parent_value = self.node.get("value")
        left_sub = self.node.get("left")
        new_crumbs = list(self.crumbs)
        new_crumbs.append(("right", parent_value, left_sub))
        return Zipper(right_sub, new_crumbs)

    def set_right(self, tree):
        if self.node is None:
            new_node = {"value": None, "left": None, "right": tree}
        else:
            new_node = {
                "value": self.node.get("value"),
                "left": self.node.get("left"),
                "right": tree,
            }
        return Zipper(new_node, list(self.crumbs))

    def up(self):
        if not self.crumbs:
            return None
        direction, parent_value, other = self.crumbs[-1]
        rest = list(self.crumbs[:-1])
        if direction == "left":
            # we came up from left child; other is right subtree
            new_node = {"value": parent_value, "left": self.node, "right": other}
        else:  # 'right'
            # came up from right child; other is left subtree
            new_node = {"value": parent_value, "left": other, "right": self.node}
        return Zipper(new_node, rest)

    def to_tree(self):
        z = self
        while True:
            upz = z.up()
            if upz is None:
                return z.node
            z = upz
